// utils/mediators/{mediator}/{Mediator}Mediator.ts
// Mediator — {Mediator} coordonne les composants sans qu'ils se connaissent

// Interface des composants enregistrés
export interface {Mediator}Component {
  getName(): string
  getValue(): unknown
  setValue(value: unknown): void
  validate(): boolean
}

export class {Mediator}Mediator {
  private components: Map<string, {Mediator}Component> = new Map()

  // Enregistrement d'un composant
  register(component: {Mediator}Component): void {
    this.components.set(component.getName(), component)
  }

  unregister(name: string): void {
    this.components.delete(name)
  }

  // Communication centralisée — les composants passent par ici
  notify(sender: string, event: string, data?: unknown): void {
    // Ajoute ici la logique de coordination
    // Exemple : si 'country' change, mettre à jour 'region'
    this.components.forEach((component, name) => {
      if (name !== sender) {
        this.handleEvent(name, component, event, data)
      }
    })
  }

  private handleEvent(
    componentName: string,
    component: {Mediator}Component,
    event: string,
    data?: unknown
  ): void {
    // Ajoute ici les règles de coordination spécifiques
    // Exemple :
    // if (event === 'country-changed' && componentName === 'region') {
    //   component.setValue(data === 'FR' ? 'Île-de-France' : '')
    // }
  }

  setField(name: string, value: unknown): void {
    this.components.get(name)?.setValue(value)
  }

  validateAll(): boolean {
    return [...this.components.values()].every(c => c.validate())
  }

  getData(): Record<string, unknown> {
    const data: Record<string, unknown> = {}
    this.components.forEach((component, name) => {
      data[name] = component.getValue()
    })
    return data
  }
}

// composables/{mediator}/use{Mediator}Mediator.ts
import { {Mediator}Mediator } from '~/utils/mediators/{mediator}/{Mediator}Mediator'
import type { {Mediator}Component } from '~/utils/mediators/{mediator}/{Mediator}Mediator'

export const use{Mediator}Mediator = () => {
  const mediator = new {Mediator}Mediator()

  // Crée et enregistre un composant réactif
  const registerField = (
    name: string,
    initialValue: unknown,
    validate: () => boolean = () => true
  ) => {
    const value = ref(initialValue)

    const component: {Mediator}Component = {
      getName:  () => name,
      getValue: () => value.value,
      setValue: (v) => { value.value = v },
      validate
    }

    mediator.register(component)

    // Notifier le médiateur à chaque changement
    watch(value, () => mediator.notify(name, `${name}-changed`, value.value))

    // Se désinscrire au démontage du composant
    onUnmounted(() => mediator.unregister(name))

    return value
  }

  const submit = () => {
    if (!mediator.validateAll()) return null
    return mediator.getData()
  }

  return { mediator, registerField, submit }
}

// tests/utils/mediators/{mediator}/{Mediator}Mediator.spec.ts
import { describe, it, expect, vi } from 'vitest'
import { {Mediator}Mediator } from '~/utils/mediators/{mediator}/{Mediator}Mediator'
import type { {Mediator}Component } from '~/utils/mediators/{mediator}/{Mediator}Mediator'

const makeComponent = (name: string, value: unknown = ''): {Mediator}Component => {
  let _value = value
  return {
    getName:  () => name,
    getValue: () => _value,
    setValue: (v) => { _value = v },
    validate: () => !!_value
  }
}

describe('{Mediator}Mediator', () => {

  it('register() et getData() fonctionnent', () => {
    const m = new {Mediator}Mediator()
    m.register(makeComponent('name', 'Alice'))
    m.register(makeComponent('email', 'alice@test.com'))
    expect(m.getData()).toEqual({ name: 'Alice', email: 'alice@test.com' })
  })

  it('setField() met à jour la valeur du composant', () => {
    const m   = new {Mediator}Mediator()
    const comp = makeComponent('field', '')
    m.register(comp)
    m.setField('field', 'nouvelle valeur')
    expect(comp.getValue()).toBe('nouvelle valeur')
  })

  it('validateAll() retourne true si tous les composants sont valides', () => {
    const m = new {Mediator}Mediator()
    m.register(makeComponent('a', 'valeur-a'))
    m.register(makeComponent('b', 'valeur-b'))
    expect(m.validateAll()).toBe(true)
  })

  it('validateAll() retourne false si un composant est invalide', () => {
    const m = new {Mediator}Mediator()
    m.register(makeComponent('a', 'valeur'))
    m.register(makeComponent('b', ''))  // vide = invalide
    expect(m.validateAll()).toBe(false)
  })

  it('unregister() retire le composant', () => {
    const m = new {Mediator}Mediator()
    m.register(makeComponent('field', 'val'))
    m.unregister('field')
    expect(m.getData()).toEqual({})
  })

})
